import React, { useState, useCallback, useMemo, useEffect } from 'react';
import { Node, Edge } from '@xyflow/react';
import { ListView } from './components/ListView';
import { generateImage, generatePromptFromTree, generateModificationPrompt } from './services/aiService';

const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="flex items-center px-2">
    <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] normal-case">
      {children}
    </span>
  </div>
);

const PillButton: React.FC<{
  icon?: React.ReactNode; children: React.ReactNode;
  variant?: 'filled' | 'outline' | 'solid'; onClick?: () => void;
  disabled?: boolean;
}> = ({ icon, children, variant = 'filled', onClick, disabled }) => {
  const base = 'flex items-center gap-[2px] justify-center w-full h-[34px] rounded-xl font-medium tracking-[0.1px] transition-all cursor-pointer';
  const variants: Record<string, string> = {
    filled: 'bg-[#969696] hover:bg-[#a6a6a6] active:bg-[#868686] text-black text-[11px] pl-[8px] pr-[24px] py-1 select-none disabled:opacity-30 disabled:cursor-not-allowed',
    outline: 'border border-[#595959] hover:bg-white/5 active:bg-white/10 backdrop-blur-[40px] text-[12px] pl-[8px] pr-[16px] py-2 text-white select-none disabled:opacity-30 disabled:cursor-not-allowed',
    solid: 'bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[12px] pl-[8px] pr-[16px] py-2 select-none disabled:opacity-30 disabled:cursor-not-allowed',
  };
  return (
    <button className={`${base} ${variants[variant]}`} onClick={onClick} disabled={disabled}>
      {icon && <span className="flex items-center justify-center w-6 h-6">{icon}</span>}
      <span>{children}</span>
    </button>
  );
};

const SegmentedToggle: React.FC<{
  value: string; items: { value: string; label: string; icon?: React.ReactNode }[];
  onChange: (val: string) => void;
}> = ({ value, items, onChange }) => (
  <div className="flex w-full items-center border border-[#595959] rounded-xl overflow-hidden bg-transparent">
    {items.map((item) => (
      <button key={item.value} type="button" onClick={() => onChange(item.value)}
        className={`flex-1 flex items-center justify-center gap-1 h-[34px] px-3 py-2 rounded-xl text-[12px] font-medium tracking-[0.1px] transition-all cursor-pointer ${
          value === item.value ? 'bg-[#969696] text-black' : 'text-[rgba(218,220,224,0.75)] hover:text-white hover:bg-white/5'
        }`}>
        {item.icon}<span>{item.label}</span>
      </button>
    ))}
  </div>
);

const OnboardingModal = ({ onComplete }: { onComplete: () => void }) => {
  const [step, setStep] = useState(0);
  const steps = [
    { 
      title: "List the Details", 
      desc: "Start by entering the main subject of your image. Continue adding as many details and subdetails to your prompt tree as you like.", 
      icon: "add_circle" 
    },
    { 
      title: "AI Writes the Rest", 
      desc: "The app will translate your prompt tree into an optimized prompt for your image generation.", 
      icon: "auto_awesome" 
    },
    { 
      title: "Make Edits", 
      desc: "After your generation is complete, you can make changes to your prompt tree. The app will interpret those changes and create a specific prompt to make those changes to your image.", 
      icon: "edit_square" 
    }
  ];

  const current = steps[step];

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm">
      <div className="bg-[#1a1a1a] border border-[#595959] rounded-2xl w-[320px] p-8 flex flex-col gap-6 shadow-2xl animate-dropdown origin-center">
        <div className="w-12 h-12 rounded-2xl bg-white/5 flex items-center justify-center border border-white/10 mx-auto">
          <span className="material-symbols-outlined text-[24px] text-white">{current.icon}</span>
        </div>
        <div className="text-center">
          <h2 className="text-lg font-semibold text-white mb-2">{current.title}</h2>
          <p className="text-[13px] text-white/50 leading-relaxed">{current.desc}</p>
        </div>
        <div className="flex items-center justify-between mt-4">
          <div className="flex gap-1.5">
            {steps.map((_, i) => (
              <div key={i} className={`h-1.5 rounded-full transition-all ${i === step ? 'bg-white w-6' : 'bg-white/20 w-1.5'}`} />
            ))}
          </div>
          <button 
            onClick={() => step < 2 ? setStep(step + 1) : onComplete()}
            className="flex items-center gap-1.5 bg-white text-black px-5 py-1.5 rounded-xl text-[12px] font-semibold hover:bg-gray-200 transition-colors"
          >
            {step === 2 ? 'Start' : 'Next'}
            <span className="material-symbols-outlined text-[16px]">{step === 2 ? 'check' : 'chevron_right'}</span>
          </button>
        </div>
      </div>
    </div>
  );
};

export default function App() {
  useEffect(() => {
    const id = 'flow-design-system-css';
    if (document.getElementById(id)) return;
    const style = document.createElement('style');
    style.id = id;
    style.textContent = `
      input[type=range] { -webkit-appearance: none; appearance: none; background: transparent; width: 100%; cursor: pointer; padding: 8px 0; }
      input[type=range]::-webkit-slider-runnable-track { width: 100%; height: 3px; background: #595959; border-radius: 9999px; }
      input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 14px; height: 14px; border-radius: 50%; background: white; box-shadow: 0px 1px 3px rgba(0,0,0,0.5); margin-top: -5.5px; cursor: grab; }
      .dark-scrollbar::-webkit-scrollbar { width: 6px; }
      .dark-scrollbar::-webkit-scrollbar-thumb { background: #595959; border-radius: 10px; }
      @keyframes dropdown-enter { from { opacity: 0; transform: scale(0.95); } to { opacity: 1; transform: scale(1); } }
      .animate-dropdown { animation: dropdown-enter 0.2s ease-out forwards; }
      html, body, #root { margin: 0; padding: 0; width: 100%; height: 100%; background: #0e0e0e; font-family: 'Google Sans Text', sans-serif; }
    `;
    document.head.appendChild(style);

    const xyid = 'xyflow-css';
    if (!document.getElementById(xyid)) {
      const link = document.createElement('link');
      link.id = xyid;
      link.rel = 'stylesheet';
      link.href = 'https://unpkg.com/@xyflow/react@12.10.1/dist/style.css';
      document.head.appendChild(link);
    }
  }, []);

  const [nodes, setNodes] = useState<Node[]>([{ id: '1', type: 'custom', position: { x: 0, y: 0 }, data: { label: '', placeholder: 'Main Subject...' } }]);
  const [edges, setEdges] = useState<Edge[]>([]);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [aspectRatio, setAspectRatio] = useState('1:1');
  const [focusedNodeId, setFocusedNodeId] = useState<string | null>(null);
  const [lastHierarchy, setLastHierarchy] = useState<any>(null);
  const [showOnboarding, setShowOnboarding] = useState(true);

  const activePath = useMemo(() => {
    if (!focusedNodeId) return new Set<string>();
    const path = new Set<string>([focusedNodeId]);
    let currId = focusedNodeId;
    const parentMap = new Map<string, string>();
    edges.forEach(e => parentMap.set(e.target, e.source));
    while (parentMap.has(currId)) {
      currId = parentMap.get(currId)!;
      path.add(currId);
    }
    return path;
  }, [focusedNodeId, edges]);

  // Derive current tree structure for comparison
  const currentHierarchy = useMemo(() => {
    const nodeMap = new Map();
    nodes.forEach(n => nodeMap.set(n.id, { label: n.data.label, children: [] }));
    edges.forEach(e => {
      const parent = nodeMap.get(e.source);
      const child = nodeMap.get(e.target);
      if (parent && child) parent.children.push(child);
    });
    const targetIds = new Set(edges.map(e => e.target));
    return nodes.filter(n => !targetIds.has(n.id)).map(n => nodeMap.get(n.id));
  }, [nodes, edges]);

  // Check if current tree is different from the last generated one
  const isModified = useMemo(() => {
    if (!lastHierarchy) return true; // Always allow first generation
    return JSON.stringify(currentHierarchy) !== JSON.stringify(lastHierarchy);
  }, [currentHierarchy, lastHierarchy]);

  const handleNodeChange = useCallback((id: string, newLabel: string) => {
    setNodes(nds => nds.map(n => n.id === id ? { ...n, data: { ...n.data, label: newLabel } } : n));
  }, []);

  const handleAddChild = useCallback((parentId: string) => {
    const newId = crypto.randomUUID();
    const newNode: Node = { id: newId, type: 'custom', position: { x: 0, y: 0 }, data: { label: '', placeholder: 'Add detail...' } };
    setNodes(nds => [...nds, newNode]);
    setEdges(eds => [...eds, { id: `e-${parentId}-${newId}`, source: parentId, target: newId }]);
    setFocusedNodeId(newId);
  }, []);

  const handleAddSibling = useCallback((nodeId: string) => {
    const parentEdge = edges.find(e => e.target === nodeId);
    if (parentEdge) handleAddChild(parentEdge.source);
    else {
      const newId = crypto.randomUUID();
      setNodes(nds => [...nds, { id: newId, type: 'custom', position: { x: 0, y: 0 }, data: { label: '', placeholder: 'Main Subject...' } }]);
      setFocusedNodeId(newId);
    }
  }, [edges, handleAddChild]);

  const handleDeleteNode = useCallback((id: string) => {
    const descendants = new Set<string>();
    const stack = [id];
    while (stack.length > 0) {
      const curr = stack.pop()!;
      descendants.add(curr);
      edges.filter(e => e.source === curr).forEach(e => stack.push(e.target));
    }

    // If we are deleting the entire tree (all nodes are descendants of the node being deleted),
    // reset to a single empty field instead of deleting the node.
    if (descendants.size === nodes.length) {
      setNodes([{ id: '1', type: 'custom', position: { x: 0, y: 0 }, data: { label: '', placeholder: 'Main Subject...' } }]);
      setEdges([]);
      setFocusedNodeId('1');
      return;
    }

    setNodes(nds => nds.filter(n => !descendants.has(n.id)));
    setEdges(eds => eds.filter(e => !descendants.has(e.source) && !descendants.has(e.target)));
    if (focusedNodeId && descendants.has(focusedNodeId)) setFocusedNodeId(null);
  }, [nodes, edges, focusedNodeId]);

  const handleKeyDown = useCallback((e: React.KeyboardEvent, nodeId: string) => {
    if (e.key === 'Tab') { e.preventDefault(); handleAddChild(nodeId); }
    else if (e.key === 'Enter') { e.preventDefault(); handleAddSibling(nodeId); }
  }, [handleAddChild, handleAddSibling]);

  const handleGenerate = async () => {
    setIsGenerating(true);
    try {
      const roots = currentHierarchy;
      let finalBase64 = "";
      if (generatedImage && lastHierarchy) {
        const modification = await generateModificationPrompt(lastHierarchy, roots);
        finalBase64 = await generateImage(modification, aspectRatio, generatedImage);
      } else {
        const fullPrompt = await generatePromptFromTree(roots);
        finalBase64 = await generateImage(fullPrompt, aspectRatio);
      }
      setGeneratedImage(finalBase64);
      setLastHierarchy(roots);
    } catch (err) {
      console.error(err);
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="flex h-screen w-screen bg-[#0e0e0e] text-white overflow-hidden font-['Google_Sans_Text']">
      {showOnboarding && <OnboardingModal onComplete={() => setShowOnboarding(false)} />}

      {/* Editor Panel */}
      <div className="flex-1 flex flex-col border-r border-[rgba(218,220,224,0.15)] bg-[#0e0e0e]">
        <div className="h-16 px-6 border-b border-[rgba(218,220,224,0.15)] flex items-center justify-end">
          <div className="flex items-center gap-2">
            <span className="text-[11px] text-white/30 uppercase font-bold tracking-widest mr-2">Aspect</span>
            <div className="w-[180px]">
              <SegmentedToggle 
                value={aspectRatio}
                onChange={setAspectRatio}
                items={[
                  { value: '1:1', label: '1:1' },
                  { value: '16:9', label: '16:9' },
                  { value: '9:16', label: '9:16' }
                ]}
              />
            </div>
          </div>
        </div>
        <ListView
          nodes={nodes}
          edges={edges}
          onNodeChange={handleNodeChange}
          onAddChild={handleAddChild}
          onDeleteNode={handleDeleteNode}
          focusedNodeId={focusedNodeId}
          onFocus={setFocusedNodeId}
          activePath={activePath}
          onKeyDown={handleKeyDown}
        />
      </div>

      {/* Output Panel */}
      <div className="w-[400px] flex flex-col items-start justify-between border-l border-[rgba(218,220,224,0.15)] p-[10px] py-[12px] h-full min-h-0 bg-[#0e0e0e]">
        <div className="flex flex-col gap-[24px] items-start w-full h-full">
          <SectionLabel>Generated Output</SectionLabel>

          <div className="flex-1 w-full bg-white/5 rounded-2xl border border-white/10 overflow-hidden relative group">
            {isGenerating ? (
              <div className="absolute inset-0 flex flex-col items-center justify-center gap-4 text-center p-8">
                <div className="w-10 h-10 border-t-2 border-white rounded-full animate-spin" />
                <p className="text-xs text-white/40 font-medium">Synthesizing Vision...</p>
              </div>
            ) : generatedImage ? (
              <img src={`data:image/png;base64,${generatedImage}`} className="w-full h-full object-contain" />
            ) : (
              <div className="absolute inset-0 flex flex-col items-center justify-center gap-3 text-white/20">
                <span className="material-symbols-outlined text-[32px]">photo_library</span>
                <p className="text-[11px] font-medium">Ready to visualize</p>
              </div>
            )}
          </div>
        </div>

        <div className="flex flex-col gap-[5px] items-start w-full pt-4">
          <PillButton 
            variant="solid" 
            onClick={handleGenerate} 
            disabled={isGenerating || !isModified}
          >
            {isGenerating ? 'Generating...' : 'Generate Image'}
          </PillButton>
          {generatedImage && (
            <PillButton variant="outline" onClick={() => { setGeneratedImage(null); setLastHierarchy(null); }} icon={<span className="material-symbols-outlined text-[18px]">delete</span>}>
              Clear
            </PillButton>
          )}
        </div>
      </div>
    </div>
  );
}

import React, { useEffect, useRef, useState } from 'react';
import { Node, Edge } from '@xyflow/react';

interface ListViewProps {
  nodes: Node[];
  edges: Edge[];
  onNodeChange: (id: string, label: string) => void;
  onAddChild: (parentId: string) => void;
  onDeleteNode: (id: string) => void;
  focusedNodeId: string | null;
  onFocus: (id: string | null) => void;
  activePath: Set<string>;
  onKeyDown: (e: React.KeyboardEvent, id: string) => void;
}

const ListNode = ({ 
  node, 
  depth, 
  onNodeChange, 
  onAddChild, 
  onDeleteNode, 
  isActive,
  isInPath,
  onFocus,
  onKeyDown,
  isCollapsed,
  toggleCollapse,
  renderNode,
  children
}: any) => {
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isActive && inputRef.current) {
      inputRef.current.focus();
    }
  }, [isActive]);

  const hasChildren = children.length > 0;

  return (
    <div className="flex flex-col w-full">
      <div className={`flex items-center gap-3 group relative py-1 ${depth === 0 ? 'mt-6 mb-2' : ''}`}>
        {/* Connection Line */}
        {depth > 0 && (
          <div className={`absolute -left-5 top-1/2 w-5 h-[1px] transition-colors ${isInPath ? 'bg-white/40' : 'bg-white/10'}`} />
        )}

        {/* Toggle / Bullet */}
        <div className="w-5 h-5 flex items-center justify-center shrink-0 z-10">
          {hasChildren ? (
            <button
              onClick={() => toggleCollapse(node.id)}
              className={`material-symbols-outlined text-[18px] transition-colors cursor-pointer ${isInPath ? 'text-white' : 'text-white/40 hover:text-white'}`}
            >
              {isCollapsed ? 'chevron_right' : 'expand_more'}
            </button>
          ) : (
            <div className={`rounded-full transition-all duration-300 ${
              depth === 0 
                ? isInPath ? 'w-2 h-2 bg-white shadow-[0_0_8px_rgba(255,255,255,0.5)]' : 'w-2 h-2 bg-white/20'
                : isInPath ? 'w-1.5 h-1.5 bg-white' : 'w-1.5 h-1.5 bg-white/10'
            }`} />
          )}
        </div>

        {/* Input Field */}
        <div className="flex-1">
          <input
            ref={inputRef}
            value={node.data.label}
            onChange={(e) => onNodeChange(node.id, e.target.value)}
            onFocus={() => onFocus(node.id)}
            onKeyDown={(e) => onKeyDown(e, node.id)}
            className={`bg-transparent outline-none w-full py-1.5 px-2 rounded-lg hover:bg-white/5 transition-all ${
              depth === 0 ? 'text-lg font-medium' : 'text-sm'
            } ${isActive ? 'text-white' : isInPath ? 'text-white/80' : 'text-white/40'}`}
            placeholder={node.data.placeholder}
          />
        </div>

        {/* Actions */}
        <div className={`flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity pr-2`}>
          <button 
            onClick={() => {
              onAddChild(node.id);
              if (isCollapsed) toggleCollapse(node.id);
            }} 
            className="material-symbols-outlined text-[18px] text-white/40 hover:text-white p-1 hover:bg-white/10 rounded-lg cursor-pointer"
          >
            add
          </button>
          <button 
            onClick={() => onDeleteNode(node.id)} 
            className="material-symbols-outlined text-[18px] text-white/40 hover:text-red-400 p-1 hover:bg-red-500/10 rounded-lg cursor-pointer"
          >
            delete
          </button>
        </div>
      </div>

      {!isCollapsed && hasChildren && (
        <div className="flex flex-col w-full ml-2.5 pl-5 relative">
          <div className={`absolute left-0 top-0 bottom-0 w-[1px] transition-colors ${
            isInPath ? 'bg-white/20' : 'bg-white/5'
          }`} />
          {children.map((child: any) => renderNode(child, depth + 1))}
        </div>
      )}
    </div>
  );
};

export function ListView({ nodes, edges, onNodeChange, onAddChild, onDeleteNode, focusedNodeId, onFocus, activePath, onKeyDown }: ListViewProps) {
  const [collapsed, setCollapsed] = useState<Set<string>>(new Set());

  const toggleCollapse = (id: string) => {
    setCollapsed(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const nodeMap = new Map();
  nodes.forEach(n => nodeMap.set(n.id, { ...n, children: [] }));

  edges.forEach(e => {
    const parent = nodeMap.get(e.source);
    const child = nodeMap.get(e.target);
    if (parent && child) parent.children.push(child);
  });

  const targetIds = new Set(edges.map(e => e.target));
  const roots = nodes.filter(n => !targetIds.has(n.id)).map(n => nodeMap.get(n.id));

  const renderNode = (node: any, depth: number = 0) => {
    return (
      <ListNode
        key={node.id}
        node={node}
        depth={depth}
        children={node.children}
        onNodeChange={onNodeChange}
        onAddChild={onAddChild}
        onDeleteNode={onDeleteNode}
        isActive={focusedNodeId === node.id}
        isInPath={activePath.has(node.id)}
        onFocus={onFocus}
        onKeyDown={onKeyDown}
        isCollapsed={collapsed.has(node.id)}
        toggleCollapse={toggleCollapse}
        renderNode={renderNode}
      />
    );
  };

  return (
    <div className="w-full h-full overflow-y-auto px-10 py-12 dark-scrollbar"
      onClick={(e) => { if (e.target === e.currentTarget) onFocus(null); }}>
      <div className="w-full max-w-2xl mx-auto flex flex-col">
        {roots.map(root => renderNode(root, 0))}
      </div>
    </div>
  );
}

import { Flow } from "flow-sdk";

export async function generatePromptFromTree(tree: any): Promise<string> {
  const prompt = `
    Analyze this hierarchical visual description and synthesize it into a single, cohesive image prompt.
    Include details about subject, style, lighting, and composition.

    Hierarchy:
    ${JSON.stringify(tree, null, 2)}

    Output ONLY the final prompt paragraph.
  `;

  const response = await Flow.generate.text(prompt, { thinkingLevel: 'low' });
  return response.text || 'A cinematic masterpiece based on tree structure.';
}

export async function generateModificationPrompt(oldTree: any, newTree: any): Promise<string> {
  const prompt = `
    Compare the old and new hierarchical descriptions.
    Identify additions or alterations.
    Write a short instruction to modify an existing image to match the new state.

    Old: ${JSON.stringify(oldTree, null, 2)}
    New: ${JSON.stringify(newTree, null, 2)}

    Output ONLY the change instruction.
  `;

  const response = await Flow.generate.text(prompt, { thinkingLevel: 'low' });
  return response.text || 'Apply subtle refinements to the scene.';
}

export async function generateImage(prompt: string, aspectRatio: string = '1:1', previousImageBase64?: string): Promise<string> {
  const options: any = {
    prompt,
    aspectRatio: aspectRatio as any,
    modelDisplayName: 'Nano Banana Pro'
  };

  if (previousImageBase64) {
    const { mediaId } = await Flow.upload({
      base64: previousImageBase64,
      mimeType: 'image/png'
    });
    options.referenceImageMediaIds = [mediaId];
  }

  const result = await Flow.generate.image(options);
  return result.base64;
}
